import React,{useEffect,useMemo,useState}from'react';import{Routes,Route,NavLink,useNavigate,useLocation}from'react-router-dom';import{LayoutDashboard,Users,BookOpen,Layers,GraduationCap,CalendarCheck,Wallet,Settings,Search,Bell,ChevronDown,Plus,ArrowUpRight,MoreHorizontal,Menu,X,LogOut,Clock3,ArrowDownLeft,Download,ArrowUpRight as Up,ShieldCheck,UserRound,LockKeyhole,Eye,EyeOff,CheckCircle2,AlertCircle,LoaderCircle}from'lucide-react';import api from './api.js';
const nav=[['Overview',LayoutDashboard,'/'],['Students',Users,'/students'],['Courses',BookOpen,'/courses'],['Batches',Layers,'/batches'],['Trainers',GraduationCap,'/trainers'],['Attendance',CalendarCheck,'/attendance'],['Fee payments',Wallet,'/payments'],['Certificates',ShieldCheck,'/certificates']];const roleName=r=>r?.[0]?.toUpperCase()+r?.slice(1);const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n||0);const date=d=>d?new Date(d).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}):'—';
function App(){const [user,setUser]=useState(()=>JSON.parse(localStorage.getItem('atlas_user')||'null'));const [mobile,setMobile]=useState(false);const [instituteName,setInstituteName]=useState(import.meta.env.VITE_INSTITUTE_NAME||'Software Training Institute Management System');const navto=useNavigate(),loc=useLocation();useEffect(()=>{api.get('/settings/public').then(r=>setInstituteName(r.data.instituteName)).catch(()=>{});},[]);useEffect(()=>{document.title=instituteName;},[instituteName]);useEffect(()=>{if(!user&&loc.pathname!=='/login'&&loc.pathname!=='/register')navto('/login');},[user,loc.pathname]);const logout=()=>{localStorage.clear();setUser(null);navto('/login')};const title=nav.find(n=>n[2]===loc.pathname)?.[0]||'My learning';return <>{user&&<div className={`app-shell role-${user.role}`}><aside className={`sidebar ${mobile?'open':''}`}><div className="brand"><div className="brand-mark">S</div><div className="brand-name"><strong>{instituteName}</strong><small>LEARNING MANAGEMENT</small></div><button className="icon-btn mobile-close" onClick={()=>setMobile(false)}><X size={18}/></button></div><div className="workspace"><div className="workspace-icon">N</div><div><b>{instituteName}</b><small>Training campus</small></div><ChevronDown size={15}/></div><div className="nav-caption">WORKSPACE</div><nav>{(user.role==='student'?[['My learning',LayoutDashboard,'/'],['Learning materials',BookOpen,'/learning'],['Assignments',Layers,'/assignments'],['My attendance',CalendarCheck,'/attendance'],['My payments',Wallet,'/payments'],['Certificates',ShieldCheck,'/certificates']]:user.role==='trainer'?[['Overview',LayoutDashboard,'/'],['My batches',Layers,'/batches'],['Attendance',CalendarCheck,'/attendance'],['Learning materials',BookOpen,'/learning'],['Assignments',Layers,'/assignments'],['Completions',ShieldCheck,'/completions']]:nav).map(([label,Icon,path])=><NavLink onClick={()=>setMobile(false)} className={({isActive})=>`nav-item ${isActive?'active':''}`} key={path} to={path}><Icon size={18}/><span>{label}</span>{label==='Students'&&<em>2</em>}</NavLink>)}</nav><div className="sidebar-bottom"><div className="help-card"><div className="help-icon"><ShieldCheck size={17}/></div><b>Everything in sync</b><p>Your campus data is up to date.</p><div className="sync-row"><i/> Connected <span>v1.0.0</span></div></div><button className="nav-item"><Settings size={18}/> Settings</button><button className="profile" onClick={logout}><div className="avatar">{user.name?.split(' ').map(x=>x[0]).join('').slice(0,2)}</div><div><b>{user.name}</b><small>{roleName(user.role)}</small></div><LogOut size={16}/></button></div></aside>{mobile&&<div className="scrim" onClick={()=>setMobile(false)}/>}<main className="main"><header className="topbar"><button className="icon-btn menu-btn" onClick={()=>setMobile(true)}><Menu size={20}/></button><div className="crumb">Workspace <span>/</span> <b>{title}</b></div><div className="top-right"><div className="today-pill"><i/> All systems normal</div><button className="icon-btn notification"><Bell size={18}/><i/></button><button className="top-profile" onClick={logout} title="Sign out"><div className="top-avatar">{user.name?.[0]}</div><div className="top-user"><b>{user.name}</b><small>{roleName(user.role)} · Sign out</small></div><LogOut size={15}/></button></div></header><div className="page-wrap"><Routes><Route path="/" element={user.role==='student'?<Portal/>:user.role==='trainer'?<TrainerHome/>:<Dashboard/>}/><Route path="/students" element={user.role==='admin'?<Students user={user}/>:<Portal/>}/><Route path="/courses" element={user.role==='admin'?<Courses user={user}/>:<TrainerHome/>}/><Route path="/batches" element={user.role==='admin'?<Batches user={user}/>:<TrainerHome/>}/><Route path="/trainers" element={user.role==='admin'?<Trainers user={user}/>:<TrainerHome/>}/><Route path="/attendance" element={user.role==='student'?<StudentAttendance/>:user.role==='admin'?<AdminAttendance/>:<AttendancePage user={user}/>}/><Route path="/payments" element={<Payments user={user}/>}/><Route path="/learning" element={<LearningPage user={user} mode="materials"/>}/><Route path="/assignments" element={<LearningPage user={user} mode="assignments"/>}/><Route path="/completions" element={user.role==='trainer'?<Completions/>:<Dashboard/>}/><Route path="/certificates" element={<Certificates user={user}/>}/><Route path="*" element={<Dashboard/>}/></Routes></div></main></div>}<Routes><Route path="/login" element={!user?<Auth mode="login" onAuth={setUser} instituteName={instituteName}/>:<Redirect/>}/><Route path="/register" element={!user?<Auth mode="register" onAuth={setUser} instituteName={instituteName}/>:<Redirect/>}/></Routes></>}
function Redirect(){const n=useNavigate();useEffect(()=>n('/'),[]);return null}
function Auth({mode,onAuth,instituteName}){const[form,setForm]=useState({}),[err,setErr]=useState(''),[busy,setBusy]=useState(false),[show,setShow]=useState(false);const navto=useNavigate();const submit=async e=>{e.preventDefault();setErr('');setBusy(true);try{const r=await api.post(`/auth/${mode}`,form);localStorage.setItem('atlas_token',r.data.token);localStorage.setItem('atlas_user',JSON.stringify(r.data.user));onAuth(r.data.user);navto('/')}catch(e){setErr(e.response?.data?.message||'Unable to connect to the server. Check that the API is running.')}finally{setBusy(false)}};return <div className="auth-page"><div className="auth-left"><div className="auth-brand"><div className="brand-mark">S</div><b>{instituteName}</b><small>LEARNING MANAGEMENT</small></div><div className="auth-hero"><div className="eyebrow"><i/> BUILT FOR MODERN LEARNING</div><h1>Great learning.<br/><em>Better managed.</em></h1><p>One calm, clear workspace for the people, programs, and progress that make your institute thrive.</p><div className="auth-mini"><div className="stack-avatars"><i>A</i><i>M</i><i>R</i><i>+</i></div><span>Trusted by ambitious<br/>learning communities</span></div></div><div className="auth-decoration"><div className="orbit o1"/><div className="orbit o2"/><div className="auth-dot d1"/><div className="auth-dot d2"/><div className="auth-orb">a<span>.</span></div></div><div className="auth-foot">© 2026 {instituteName} <span>Made for what’s next.</span></div></div><div className="auth-right"><form className="auth-form" onSubmit={submit}><div className="auth-overline">{mode==='login'?'WELCOME BACK':'GET STARTED'}</div><h2>{mode==='login'?'Sign in to your institute workspace':'Create your account'}</h2><p>{mode==='login'?'Enter your details to access your workspace.':'Join your institute’s learning workspace.'}</p>{err&&<div className="error-banner"><AlertCircle size={17}/>{err}</div>}{mode==='register'&&<label>Full name<input required placeholder="e.g. Jordan Lee" value={form.name||''} onChange={e=>setForm({...form,name:e.target.value})}/></label>}<label>Email address<input required type="email" placeholder="you@institute.com" value={form.email||''} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>Password<div className="password-field"><input required minLength="8" type={show?'text':'password'} placeholder="At least 8 characters" value={form.password||''} onChange={e=>setForm({...form,password:e.target.value})}/><button type="button" className="icon-btn" onClick={()=>setShow(!show)}>{show?<EyeOff size={17}/>:<Eye size={17}/>}</button></div></label>{mode==='register'&&<label>Phone <span className="optional">OPTIONAL</span><input placeholder="+91 98765 43210" value={form.phone||''} onChange={e=>setForm({...form,phone:e.target.value})}/></label>}<button className="primary full" disabled={busy}>{busy?<LoaderCircle className="spin" size={18}/>:<>{mode==='login'?'Sign in to workspace':'Create student account'} <ArrowUpRight size={17}/></>}</button><div className="auth-switch">{mode==='login'?<>New to the institute? <a href="/register">Create a student account</a></>:<>Already have an account? <a href="/login">Sign in</a></>}</div><div className="secure-note"><LockKeyhole size={14}/> Your information is encrypted and secure</div></form><div className="auth-right-foot">NEED A HAND? <a href="mailto:support@example.com">CONTACT YOUR ADMINISTRATOR ↗</a></div></div></div>}
function PageHead({eyebrow,title,desc,action}){return <div className="page-head"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{desc}</p></div>{action}</div>}
function Stat({label,value,sub,icon:Icon,kind='blue',trend}){return <div className="stat-card"><div className="stat-top"><span>{label}</span><div className={`stat-icon ${kind}`}><Icon size={19}/></div></div><div className="stat-value">{value}</div><div className="stat-bottom"><span>{sub}</span>{trend&&<span className="trend"><ArrowUpRight size={13}/>{trend}</span>}</div></div>}
function Dashboard(){const[data,setData]=useState(null),[recent,setRecent]=useState([]),[err,setErr]=useState('');useEffect(()=>{Promise.all([api.get('/dashboard'),api.get('/students')]).then(([d,s])=>{setData(d.data.stats);setRecent(s.data.slice(0,5))}).catch(e=>setErr(e.response?.data?.message||'Could not load dashboard'))},[]);return <><PageHead eyebrow="TUESDAY, OCTOBER 28, 2026" title="Good morning, welcome back" desc="Here’s what’s happening across your institute today." action={<button className="outline" onClick={()=>window.print()}><Download size={16}/> Export report</button>}/>{err&&<Notice text={err}/>}<div className="welcome-strip"><div className="welcome-art"><div className="welcome-orbit"/><div className="welcome-spark">✳</div></div><div><span>YOUR CAMPUS AT A GLANCE</span><b>A great day to make progress.</b><p>Keep an eye on attendance and outstanding fees to keep every learner on track.</p></div><div className="welcome-date"><Clock3 size={15}/> Fall term · Week 5</div></div><div className="stats-grid">{[["Total students",data?.students??'—','Across all active programs',Users,'blue','+12 this month'],['Active trainers',data?.trainers??'—','Supporting your learners',GraduationCap,'violet','+2 this term'],['Courses offered',data?.courses??'—','Curated learning paths',BookOpen,'teal',null],['Active batches',data?.batches??'—','Currently in progress',Layers,'amber',null]].map(x=><Stat key={x[0]} label={x[0]} value={x[1]} sub={x[2]} icon={x[3]} kind={x[4]} trend={x[5]}/>)}</div><div className="finance-grid"><div className="finance-card collected"><div><span>FEES COLLECTED</span><b>{money(data?.feesCollected)}</b><small><span className="green-dot"/> Payments received to date</small></div><div className="finance-icon"><ArrowDownLeft size={20}/></div><div className="finance-spark">{[30,45,38,56,44,69,56,72,60,86,68,95].map((h,i)=><i key={i} style={{height:`${h}%`}}/>)}</div></div><div className="finance-card pending"><div><span>FEES PENDING</span><b>{money(data?.pendingFees)}</b><small><span className="amber-dot"/> Outstanding across students</small></div><div className="finance-icon"><Wallet size={20}/></div><div className="pending-foot">Follow up with students <ArrowUpRight size={14}/></div></div><div className="attendance-overview"><div className="section-title"><div><span>ATTENDANCE</span><b>Campus overview</b></div><button className="more-btn"><MoreHorizontal size={20}/></button></div><div className="attendance-big"><div className="donut" style={{'--p':data?.attendance?.find(x=>x._id==='present')?.count?72:0}}><div><b>{data?.attendance?.length?`${Math.round((data.attendance.find(x=>x._id==='present')?.count||0)/(data.attendance.reduce((a,x)=>a+x.count,0))*100)}%`:'—'}</b><small>present</small></div></div><div className="att-legend"><div><i className="present-dot"/>Present <b>{data?.attendance?.find(x=>x._id==='present')?.count||0}</b></div><div><i className="absent-dot"/>Absent <b>{data?.attendance?.find(x=>x._id==='absent')?.count||0}</b></div><small>Attendance records</small></div></div><div className="att-bottom"><span>View attendance trends</span><ArrowUpRight size={14}/></div></div></div><div className="content-grid"><div className="panel"><div className="panel-head"><div><span>YOUR COMMUNITY</span><h3>Recent registrations</h3></div><a href="/students">View all <ArrowUpRight size={14}/></a></div><div className="table-wrap"><table><thead><tr><th>STUDENT</th><th>COURSE</th><th>BATCH</th><th>ENROLLED</th><th>STATUS</th></tr></thead><tbody>{recent.map(s=><tr key={s._id}><td><div className="person"><span className="avatar sm">{s.user?.name?.[0]}</span><div><b>{s.user?.name}</b><small>{s.user?.email}</small></div></div></td><td>{s.course?.name||'—'}</td><td>{s.batch?.name||'—'}</td><td>{date(s.enrollmentDate)}</td><td><span className="badge green"><i/>Active</span></td></tr>)}</tbody></table>{!recent.length&&<Empty text="No student registrations yet"/>}</div></div><div className="panel activity-panel"><div className="panel-head"><div><span>QUICK ACCESS</span><h3>Common actions</h3></div></div><div className="quick-list"><Quick icon={UserRound} title="Enroll a student" desc="Add a learner to your institute" href="/students" tone="blue"/><Quick icon={CalendarCheck} title="Attendance overview" desc="Review recorded class attendance" href="/attendance" tone="teal"/><Quick icon={Wallet} title="Record a payment" desc="Log a student fee installment" href="/payments" tone="amber"/><Quick icon={BookOpen} title="Explore courses" desc="Manage your learning programs" href="/courses" tone="violet"/></div></div></div></>}
function Quick({icon:Icon,title,desc,href,tone}){return <a className="quick-item" href={href}><div className={`quick-icon ${tone}`}><Icon size={17}/></div><div><b>{title}</b><small>{desc}</small></div><ArrowUpRight size={15}/></a>}
function Notice({text}){return <div className="error-banner"><AlertCircle size={17}/>{text}</div>}
function Empty({text}){return <div className="empty"><div className="empty-icon"><Layers size={19}/></div><b>{text}</b><small>Once there’s something here, it will show up in this space.</small></div>}
function TablePage({title,desc,endpoint,columns,createLabel,fields,adminOnly=false,recordType}){const[items,setItems]=useState([]),[query,setQuery]=useState(''),[modal,setModal]=useState(false),[editing,setEditing]=useState(null),[form,setForm]=useState({}),[busy,setBusy]=useState(false),[msg,setMsg]=useState(''),[error,setError]=useState('');const reload=()=>api.get(endpoint).then(r=>setItems(Array.isArray(r.data)?r.data:[])).catch(e=>setError(e.response?.data?.message||'Could not load records'));useEffect(()=>{reload()},[endpoint]);const filtered=items.filter(x=>JSON.stringify(x).toLowerCase().includes(query.toLowerCase()));const open=(x=null)=>{setEditing(x);const source=x?{...x,...x.user,course:x.course?._id,batch:x.batch?._id,trainer:x.trainer?._id,feePreview:x.totalFee}:{};setForm(Object.fromEntries(fields.map(f=>[f.name,source[f.name]??(f.name==='feePreview'?undefined:'')])));setError('');setModal(true)};const submit=async e=>{e.preventDefault();setBusy(true);setError('');try{if(editing)await api.put(`${endpoint}/${editing._id}`,form);else await api.post(endpoint,form);setModal(false);setForm({});setMsg(`${recordType} ${editing?'updated':'created'} successfully`);reload()}catch(e){setError(e.response?.data?.message||'Could not save record')}finally{setBusy(false)}};const remove=async id=>{if(!window.confirm(`Delete this ${recordType.toLowerCase()}? This action cannot be undone.`))return;try{await api.delete(`${endpoint}/${id}`);reload()}catch(e){setError(e.response?.data?.message||'Could not delete record')}};return <><PageHead eyebrow="INSTITUTE DIRECTORY" title={title} desc={desc} action={!adminOnly||JSON.parse(localStorage.getItem('atlas_user')||'{}').role==='admin'?<button className="primary" onClick={()=>open()}><Plus size={17}/>{createLabel}</button>:null}/>{msg&&<div className="success-banner"><CheckCircle2 size={17}/>{msg}<button onClick={()=>setMsg('')}>Dismiss</button></div>}{error&&<Notice text={error}/>}<div className="panel listing"><div className="listing-toolbar"><div className="searchbox"><Search size={16}/><input placeholder={`Search ${title.toLowerCase()}...`} value={query} onChange={e=>setQuery(e.target.value)}/><kbd>⌘ K</kbd></div><div className="toolbar-right"><button className="filter-btn">All records <ChevronDown size={14}/></button><span>{filtered.length} records</span></div></div><div className="table-wrap"><table><thead><tr>{columns.map(c=><th key={c.label}>{c.label.toUpperCase()}</th>)}<th/></tr></thead><tbody>{filtered.map((x,i)=><tr key={x._id||i}>{columns.map(c=><td key={c.label}>{c.render?c.render(x):x[c.key]||'—'}</td>)}<td><div className="row-actions"><button className="more-btn" onClick={()=>open(x)} aria-label="Edit"><Settings size={16}/></button><button className="more-btn" onClick={()=>remove(x._id)} aria-label="Delete"><X size={17}/></button></div></td></tr>)}</tbody></table>{!filtered.length&&<Empty text={`No ${title.toLowerCase()} found`}/>}</div><div className="table-footer"><span>Showing <b>{filtered.length}</b> of <b>{items.length}</b> records</span><div><button disabled>← Previous</button><button disabled>Next →</button></div></div></div>{modal&&<div className="modal-backdrop" onClick={()=>setModal(false)}><form className="modal" onSubmit={submit} onClick={e=>e.stopPropagation()}><button type="button" className="modal-x" onClick={()=>setModal(false)}><X size={18}/></button><div className="eyebrow">{editing?'UPDATE RECORD':'NEW RECORD'}</div><h2>{editing?'Edit':'Add'} {recordType}</h2><p>Enter the details below to {editing?'update':'create'} this record.</p>{fields.map(f=><label key={f.name}>{f.label}{f.type==='select'?<select required={f.required!==false} value={form[f.name]||''} onChange={e=>setForm({...form,[f.name]:e.target.value,...(f.name==='course'?{feePreview:undefined,batch:''}:{})})}><option value="">Select {f.label.toLowerCase()}</option>{(f.name==='batch'?(f.options||[]).filter(o=>!o.course||o.course===form.course):(f.options||[])).map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select>:f.type==='feePreview'?<div className="fee-preview">{form.feePreview!==undefined?money(form.feePreview):(fields.find(x=>x.name==='course')?.options?.find(o=>o.value===form.course)?.fee!==undefined?money(fields.find(x=>x.name==='course').options.find(o=>o.value===form.course).fee):'Choose a course to see its fee')}</div>:<input required={editing&&f.type==='password'?false:f.required!==false} minLength={f.minLength} type={f.type||'text'} placeholder={editing&&f.type==='password'?'Leave blank to keep current password':f.placeholder||''} value={form[f.name]||''} onChange={e=>setForm({...form,[f.name]:e.target.value})}/>}</label>)}<div className="modal-actions"><button type="button" className="outline" onClick={()=>setModal(false)}>Cancel</button><button className="primary" disabled={busy}>{busy?'Saving…':`${editing?'Save':'Create'} ${recordType}`}</button></div></form></div>}</>}
const studentCols=[{label:'STUDENT',render:s=><div className="person"><span className="avatar sm">{s.user?.name?.[0]}</span><div><b>{s.user?.name}</b><small>{s.user?.email}</small></div></div>},{label:'PHONE',render:s=>s.user?.phone||'—'},{label:'COURSE',render:s=>s.course?.name||'—'},{label:'BATCH',render:s=>s.batch?.name||'Unassigned'},{label:'FEES',render:s=><div><b>{money(s.feeSummary?.total??s.totalFee)}</b><span className={`badge ${s.feeSummary?.status==='Paid'?'green':s.feeSummary?.status==='Partial'?'amber':'rose'}`}>{s.feeSummary?.status||'—'}</span><small className="subline">Paid {money(s.feeSummary?.paid)} · Pending {money(s.feeSummary?.pending)}</small><small className="subline">Enrolled {date(s.enrollmentDate)}</small></div>}];
function Students(){const[courseOpts,setC]=useState([]),[batchOpts,setB]=useState([]);useEffect(()=>{api.get('/courses').then(r=>setC(r.data.filter(x=>x.active!==false).map(x=>({value:x._id,label:x.name,fee:x.fee}))));api.get('/batches').then(r=>setB(r.data.map(x=>({value:x._id,label:x.name,course:x.course?._id}))))},[]);return <TablePage title="Students" desc="Manage learners, enrollments, and student records." endpoint="/students" createLabel="Add student" recordType="Student" columns={studentCols} adminOnly fields={[{name:'name',label:'Full name'},{name:'email',label:'Email',type:'email'},{name:'password',label:'Temporary password',type:'password',minLength:8,placeholder:'At least 8 characters'},{name:'phone',label:'Phone',required:false},{name:'address',label:'Address',required:false},{name:'course',label:'Course',type:'select',required:false,options:courseOpts},{name:'batch',label:'Batch',type:'select',required:false,options:batchOpts},{name:'feePreview',label:'Course fee at enrollment',type:'feePreview',required:false}]}/>}
function Courses(){return <TablePage title="Courses" desc="Build and maintain your institute’s learning catalog." endpoint="/courses" createLabel="New course" recordType="Course" adminOnly columns={[{label:'COURSE',render:x=><div className="course-cell"><div className="course-icon"><BookOpen size={17}/></div><div><b>{x.name}</b><small>{x.description||'Learning program'}</small></div></div>},{label:'DURATION',key:'duration'},{label:'COURSE FEE',render:x=><b>{money(x.fee)}</b>},{label:'STATUS',render:x=><span className={`badge ${x.active?'green':'amber'}`}><i/>{x.active?'Active':'Inactive'}</span>},{label:'ADDED',render:x=>date(x.createdAt)}]} fields={[{name:'name',label:'Course name'},{name:'description',label:'Description',required:false},{name:'duration',label:'Duration',placeholder:'e.g. 24 weeks'},{name:'fee',label:'Course fee (INR)',type:'number'},{name:'active',label:'Status',type:'select',required:false,options:[{value:'true',label:'Active'},{value:'false',label:'Inactive'}]}]}/>}
function Batches(){const[courses,setC]=useState([]),[trainers,setT]=useState([]);useEffect(()=>{api.get('/courses').then(r=>setC(r.data.map(x=>({value:x._id,label:x.name}))));api.get('/trainers').then(r=>setT(r.data.map(x=>({value:x._id,label:x.user?.name||'Trainer'}))))},[]);return <TablePage title="Batches" desc="Coordinate cohorts, schedules, and teaching assignments." endpoint="/batches" createLabel="Create batch" recordType="Batch" adminOnly columns={[{label:'BATCH',render:x=><div><b>{x.name}</b><small className="subline">{x.schedule||'Schedule pending'}</small></div>},{label:'COURSE',render:x=>x.course?.name||'—'},{label:'TRAINER',render:x=>x.trainer?.user?.name||'Unassigned'},{label:'STUDENTS',render:x=><span className="count-pill">{x.students?.length||0}</span>},{label:'DATES',render:x=>`${date(x.startDate)} — ${date(x.endDate)}`},{label:'STATUS',render:x=><span className={`badge ${x.status==='active'?'green':'amber'}`}><i/>{x.status}</span>}]} fields={[{name:'name',label:'Batch name'},{name:'course',label:'Course',type:'select',options:courses},{name:'trainer',label:'Trainer',type:'select',required:false,options:trainers},{name:'startDate',label:'Start date',type:'date',required:false},{name:'endDate',label:'End date',type:'date',required:false},{name:'schedule',label:'Schedule',placeholder:'Mon, Wed, Fri · 6:30 PM',required:false},{name:'status',label:'Batch status',type:'select',required:false,options:[{value:'upcoming',label:'Upcoming'},{value:'active',label:'Active'},{value:'completed',label:'Completed'}]}]}/>}
function Trainers(){return <TablePage title="Trainers" desc="Manage your teaching team and their areas of expertise." endpoint="/trainers" createLabel="Add trainer" recordType="Trainer" adminOnly columns={[{label:'TRAINER',render:x=><div className="person"><span className="avatar sm violet-bg">{x.user?.name?.[0]}</span><div><b>{x.user?.name}</b><small>{x.user?.email}</small></div></div>},{label:'SPECIALIZATION',render:x=>x.specialization||'—'},{label:'ASSIGNED BATCHES',render:x=><span className="count-pill">{x.batches?.length||0}</span>},{label:'STATUS',render:()=> <span className="badge green"><i/>Active</span>}]} fields={[{name:'name',label:'Full name'},{name:'email',label:'Email',type:'email'},{name:'password',label:'Temporary password',type:'password',minLength:8,placeholder:'At least 8 characters'},{name:'phone',label:'Phone',required:false},{name:'specialization',label:'Specialization',required:false}]}/>}
function StudentAttendance(){const[data,setData]=useState(null),[err,setErr]=useState('');useEffect(()=>{api.get('/portal').then(r=>setData(r.data)).catch(e=>setErr(e.response?.data?.message||'Unable to load your attendance'))},[]);return <><PageHead eyebrow="STUDENT PORTAL" title="My attendance" desc="Your class attendance history and overall attendance rate."/>{err&&<Notice text={err}/>}<div className="panel attendance-side"><div className="panel-head"><div><span>ATTENDANCE HISTORY</span><h3>{data?.attendance?.percentage??0}% attendance · {data?.attendance?.present||0} of {data?.attendance?.total||0} sessions</h3></div></div><div className="history-list">{data?.attendanceHistory?.map(a=><div className="history-row" key={a._id}><div className={`history-icon ${a.status}`}><CalendarCheck size={16}/></div><div><b>{a.batch?.name||'Class session'}</b><small>{date(a.date)}</small></div><span className={`badge ${a.status==='present'?'green':'rose'}`}>{a.status}</span></div>)}{!data?.attendanceHistory?.length&&<Empty text="No attendance records yet"/>}</div></div></>}
const localToday=()=>{const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10)};
